<?php $p=__DIR__.'/tmp/sessions';if(!is_dir($p))mkdir($p,0770,true);session_save_path($p);session_start();require_once __DIR__.'/lib/workspace.php';$items=workspaceData('candidates.json',[]);$activePage='candidates';$pageTitle='Candidates · ResumeIQ';$pageStyles='<style>.workspace{display:grid;grid-template-columns:220px minmax(0,1fr) 310px;gap:10px;margin-top:12px;align-items:start}.filters,.details{padding:15px;position:sticky;top:86px}.field{margin-top:13px}.field label{display:block;font-size:9px;font-weight:600;margin-bottom:5px;color:var(--muted)}.list{overflow:hidden}.list-head{padding:13px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}.candidate-list{padding:7px}.candidate{display:grid;grid-template-columns:30px 1fr auto;gap:10px;align-items:center;padding:11px;border:1px solid transparent;border-radius:13px;cursor:pointer}.candidate:hover,.candidate.selected{background:#faf9ff;border-color:#e6e1fb}.rank{width:25px;height:25px;border-radius:8px;background:#f4f5f8;display:grid;place-items:center;font-size:9px}.person{display:flex;gap:9px;align-items:center}.photo{width:40px;height:40px;border-radius:50%;background:linear-gradient(145deg,#efeaff,#deecff);color:#5f44c7;display:grid;place-items:center;font-weight:700;font-size:10px}.name{font-size:11px;font-weight:700}.role{font-size:9px;color:var(--muted);margin:2px 0 5px}.score{text-align:right}.score strong{display:block;font-size:12px}.score span{font-size:8px;color:var(--muted)}.detail-top{display:flex;align-items:center;gap:9px;padding-bottom:12px;border-bottom:1px solid var(--line)}.detail-copy{flex:1}.detail-copy h3{margin:0;font-size:12px}.detail-copy p{margin:3px 0 0;color:var(--muted);font-size:9px}.summary{margin-top:12px;padding:11px;background:#fbfbfe;border:1px solid var(--line);border-radius:12px}.summary b{font-size:10px}.summary p{font-size:9px;color:var(--muted);line-height:1.6}.detail-section{margin-top:13px}.detail-section h4{font-size:9px;margin:0 0 7px}.skill-row{display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--line);font-size:9px}@media(max-width:1160px){.workspace{grid-template-columns:210px 1fr}.details{display:none}}@media(max-width:760px){.workspace{grid-template-columns:1fr}.filters{position:static}.candidate{grid-template-columns:25px 1fr}.score{grid-column:2}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-users"></i> Candidate intelligence</div><h1>Find the right people, faster.</h1><p>Filter by score, source, skills and experience. Review evidence before making decisions.</p></div><a class="btn btn-primary" href="index.php"><i class="fa-solid fa-cloud-arrow-up"></i>Upload resume</a></section><section class="workspace"><aside class="panel filters"><div class="panel-title">Filters</div><div class="field"><label>Search</label><input class="control" id="q" placeholder="Name or skill"></div><div class="field"><label>Source</label><select class="control" id="source"><option value="">All sources</option><?php foreach(array_unique(array_column($items,'source')) as $s):?><option><?=htmlspecialchars($s)?></option><?php endforeach?></select></div><div class="field"><label>Minimum score</label><select class="control" id="min"><option value="0">Any score</option><option value="50">50%+</option><option value="70">70%+</option><option value="85">85%+</option></select></div><div class="field"><label>Stage</label><select class="control" id="stage"><option value="">All stages</option><?php foreach(['Applied','Screening','Interview','Offer','Rejected'] as $s):?><option><?=$s?></option><?php endforeach?></select></div></aside><article class="panel list"><div class="list-head"><b>All candidates</b><span id="count"><?=count($items)?> records</span></div><div class="candidate-list"><?php foreach($items as $i=>$c):$display=array_merge($c,candidatePresentation($c));$initials=implode('',array_map(fn($x)=>mb_substr($x,0,1),array_slice(preg_split('/\s+/',trim($display['name'])),0,2)));?><div class="candidate <?=$i===0?'selected':''?>" data-json="<?=htmlspecialchars(json_encode($display),ENT_QUOTES)?>" data-find="<?=htmlspecialchars(strtolower($display['name'].' '.$display['role'].' '.implode(' ',$c['skills']??[])))?>" data-source="<?=htmlspecialchars($c['source']??'')?>" data-score="<?=(int)$c['score']?>" data-stage="<?=htmlspecialchars($c['stage']??'Applied')?>"><span class="rank"><?=$i+1?></span><div class="person"><span class="photo"><?=htmlspecialchars($initials)?></span><div><div class="name"><?=htmlspecialchars($display['name'])?></div><div class="role"><?=htmlspecialchars($display['role'])?> · <?=!empty($c['experience']['total_months'])?round($c['experience']['total_months']/12,1).' yrs':'experience unknown'?></div><div><?php foreach(array_slice($c['skills']??[],0,3) as $s):?><span class="tag"><?=htmlspecialchars($s)?></span><?php endforeach?></div></div></div><div class="score"><strong><?=(int)$c['score']?>%</strong><span>Match</span></div></div><?php endforeach?><div class="empty" id="empty" style="display:none">No candidates match these filters.</div></div></article><aside class="panel details" id="details"><div class="detail-top"><span class="photo" id="dPhoto">--</span><div class="detail-copy"><h3 id="dName">Select candidate</h3><p id="dRole">Candidate details</p></div><span class="badge" id="dScore">--</span></div><div class="summary"><b><i class="fa-solid fa-wand-magic-sparkles" style="color:var(--primary)"></i> Evidence summary</b><p id="dSummary">Select a candidate to inspect their score, timeline and skill tenure.</p></div><div class="detail-section"><h4>Skill experience estimate</h4><div id="dSkills"></div></div><div class="detail-section"><h4>Employment gaps</h4><div id="dGaps"></div></div></aside></section><script>const cards=[...document.querySelectorAll('.candidate')],q=document.getElementById('q'),src=document.getElementById('source'),min=document.getElementById('min'),stage=document.getElementById('stage');function show(c){cards.forEach(x=>x.classList.remove('selected'));c.classList.add('selected');const d=JSON.parse(c.dataset.json),initials=d.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('');dPhoto.textContent=initials;dName.textContent=d.name;dRole.textContent=(d.role||'Candidate')+' · '+(d.stage||'Applied');dScore.textContent=d.score+'%';dSummary.textContent=d.score>=70?'Strong keyword alignment. Review dated experience and missing requirements before progressing.':'Manual review recommended. The score is advisory and should be considered with recruiter evidence.';dSkills.innerHTML=Object.entries(d.experience?.skill_months||{}).map(([k,v])=>`<div class="skill-row"><span>${k}</span><b>${(v/12).toFixed(1)} yrs</b></div>`).join('')||'<span class="role">No dated skill evidence.</span>';dGaps.innerHTML=(d.experience?.gaps||[]).map(g=>`<div class="skill-row"><span>${g.after} to ${g.before}</span><b>${g.months} mo</b></div>`).join('')||'<span class="role">No gap of 2+ months detected.</span>'}cards.forEach(c=>c.onclick=()=>show(c));if(cards[0])show(cards[0]);function filter(){const s=q.value.toLowerCase(),so=src.value,m=+min.value,st=stage.value;let n=0;cards.forEach(c=>{const ok=(!s||c.dataset.find.includes(s))&&(!so||c.dataset.source===so)&&+c.dataset.score>=m&&(!st||c.dataset.stage===st);c.style.display=ok?'grid':'none';if(ok)n++});count.textContent=n+' records';empty.style.display=n?'none':'block'}[q,src,min,stage].forEach(x=>x.oninput=filter);globalSearch.oninput=e=>{q.value=e.target.value;filter()}</script>
<script>document.querySelectorAll('.candidate').forEach(card=>card.addEventListener('click',()=>{const d=JSON.parse(card.dataset.json);location.href='candidate_detail.php?id='+encodeURIComponent(d.id)}));</script>
